contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        UFixed18 amount,
        UFixed18 makerLimit,
        uint256 oracleVersion,
        uint256 timestamp,
        Fixed18 price,
        UFixed18 maintenance,
        UFixed18 fundingFee,
        UFixed18 makerFee,
        UFixed18 takerFee,
        UFixed18 positionFee,
        UFixed18 utilizationCurveMinRate,
        UFixed18 utilizationCurveMaxRate,
        UFixed18 utilizationCurveTargetRate,
        UFixed18 utilizationCurveTargetUtilization
    ) public payable {
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.VANILLA,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.POSITIVE,
            data: bytes30(0)
        });
        info.oracle = IOracleProvider(address(this));
        info.maintenance = maintenance;
        info.fundingFee = fundingFee;
        info.makerFee = makerFee;
        info.takerFee = takerFee;
        info.positionFee = positionFee;
        info.makerLimit = makerLimit;
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(int256(UFixed18.unwrap(utilizationCurveMinRate)))),
            maxRate: PackedFixed18.wrap(int128(int256(UFixed18.unwrap(utilizationCurveMaxRate)))),
            targetRate: PackedFixed18.wrap(int128(int256(UFixed18.unwrap(utilizationCurveTargetRate)))),
            targetUtilization: PackedUFixed18.wrap(uint128(UFixed18.unwrap(utilizationCurveTargetUtilization)))
        });

        c.initialize(info);

        address account = address(this);

        uint256 beforeVersion = c.latestVersion(account);
        Position memory beforePosition = c.position(account);
        uint256 beforeMaker = UFixed18.unwrap(beforePosition.maker);

        bool reverted;
        try c.openMakeFor(account, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        Position memory afterPosition = c.position(account);
        uint256 afterMaker = UFixed18.unwrap(afterPosition.maker);
        bool isClosed = c.isClosed(account);

        if (!reverted) {
            assert(afterMaker <= UFixed18.unwrap(makerLimit));
            assert(afterMaker >= beforeMaker);
            assert(!isClosed);
        }
    }

    receive() external payable {
        IOracleProvider.OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(1e18);
    }
}

