contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed, uint256 makerAmount, uint256 takerAmount) public {
        uint256 versionBefore = c.latestVersion();
        Position memory positionBefore = c.positionAtVersion(versionBefore);

        bool reverted;
        try c.updateClosed(newClosed) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.closed() == newClosed);
            assert(c.latestVersion() == versionBefore);
            Position memory positionAfter = c.positionAtVersion(versionBefore);
            assert(positionAfter.maker == positionBefore.maker && positionAfter.taker == positionBefore.taker);
        } else {
            assert(versionBefore == 0);
            assert(c.latestVersion() == versionBefore);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed, uint256 makerAmount, uint256 takerAmount) public {
        require(makerAmount == 0 && takerAmount == 0, "no position setup");

        bool wasClosed = c.closed();
        uint256 versionBefore = c.latestVersion();

        bool reverted;
        try c.updateClosed(newClosed) {
            reverted = false;
