contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 amountRaw) public payable {
        UFixed18 amount = UFixed18.wrap(amountRaw);

        uint256 versionBefore = c.latestVersion();
        Position memory posBefore = c.position(account);

        bool success;
        try c.openTakeFor(account, amount) { success = true; } catch { success = false; }

        uint256 versionAfter = c.latestVersion();
        Position memory posAfter = c.position(account);

        if (success) {
            assert(
                versionAfter == versionBefore &&
                posAfter.taker >= posBefore.taker &&
                UFixed18.unwrap(posAfter.taker) - UFixed18.unwrap(posBefore.taker) == amountRaw
            );
        }
    }

    receive() external payable {}
}

