contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, bool attemptCloseAll) public {
        // First try a non-controller call: msg.sender is this test contract, never the collateral,
        // so it must revert. Then, if requested, perform the only call that can succeed from here
        // by first checking the ordinary-path precondition before the deciding call.
        bool unauthorizedReverted;
        try c.closeAll(account) {
            unauthorizedReverted = false;
        } catch {
            unauthorizedReverted = true;
        }

        bool closedBefore = c.closed();
        bool liquidatingBefore = c.isLiquidating(account);

        // closeAll is only allowed when the product is not closed and the caller is collateral.
        // Since this test contract is not the collateral, the observable successful transition
        // can be reached only if the call would not revert for the other reasons; but the call
        // itself is the deciding transaction and must be a top-level statement.
        bool closeAllSucceeded;
        try c.closeAll(account) {
            closeAllSucceeded = true;
        } catch {
            closeAllSucceeded = false;
        }

        bool liquidatingAfter = c.isLiquidating(account);

        // General rule: because the test contract can never be the collateral address, any
        // successful closeAll call must have produced the liquidating flag regardless of input;
        // every reverting call leaves the pre-existing state unchanged.
        assert(
            (closeAllSucceeded && liquidatingAfter) ||
            (!closeAllSucceeded && liquidatingAfter == liquidatingBefore && c.closed() == closedBefore)
        );
    }

    receive() external payable {}
}

