contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(UFixed18 makeAmount, UFixed18 makerLimit_) public payable {
        IController controller = c.controller();
        uint256 coordinatorId = controller.coordinatorFor(c);
        bool isOwner = controller.owner(coordinatorId) == address(this);

        require(isOwner, "not owner");

        bool limitSet;
        bool makeReverted;

        try c.updateMakerLimit(makerLimit_) {
            limitSet = true;
        } catch {
            limitSet = false;
        }

        if (limitSet) {
            try c.openMake(makeAmount) {
                makeReverted = false;
            } catch {
                makeReverted = true;
            }

            if (makeReverted) {
                assert(makeAmount.gt(makerLimit_));
            } else {
                assert(makeAmount.lte(makerLimit_));
            }
        } else {
            assert(!limitSet);
        }
    }

    receive() external payable {}
}

