contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 makerAmount, uint256 closeAmount, uint256 takerAmount) public payable {
        // open some maker position for this contract
        require(makerAmount > 0);
        c.openMake(makerAmount);

        // Optionally open a take position too; requires collateral so keep it guarded
        // (not strictly needed for the rule)

        uint256 beforeMaker = c.position(address(this)).maker;
        uint256 beforeTaker = c.position(address(this)).taker;

        // Only meaningful when closeAmount > beforeMaker
        require(closeAmount > beforeMaker, "need over-close amount");

        bool reverted;
        try c.closeMake(closeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: over-closing must revert and leave position unchanged
        assert(reverted && c.position(address(this)).maker == beforeMaker && c.position(address(this)).taker == beforeTaker);
    }

    receive() external payable {}
}

